import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { DomainVariables, StepId, ChatMessage } from './types';
import { INITIAL_VARIABLES, PROMPT_TEMPLATE } from './constants';
import { brainstormVariables, chatWithExpert } from './services/geminiService';

// --- Styled Sketch Components ---

const SketchCard: React.FC<{ children: React.ReactNode; className?: string; rotate?: string }> = ({ children, className = "", rotate = "-0.5deg" }) => (
  <div 
    className={`relative p-6 border-2 border-zinc-700 bg-zinc-900/50 sketch-border shadow-[4px_4px_0px_0px_#27272a] transition-all duration-300 hover:shadow-[4px_4px_0px_0px_#f97316] ${className}`}
    style={{ transform: `rotate(${rotate})` }}
  >
    {children}
  </div>
);

const HighlightLabel: React.FC<{ text: string }> = ({ text }) => (
  <span className="handwritten text-orange-500 bg-orange-500/10 px-1 py-0.5 rounded-sm border-b border-orange-500/40 animate-glow">
    {text || "???"}
  </span>
);

const HandwrittenTitle: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = "" }) => (
  <h3 className={`handwritten text-orange-500 text-lg mb-4 ${className}`}>{children}</h3>
);

const VerticalStepIndicator: React.FC<{ current: StepId; onClick: (s: StepId) => void }> = ({ current, onClick }) => {
  const steps: { id: StepId; label: string }[] = [
    { id: 'identity', label: '1. Identity' },
    { id: 'context', label: '2. Context' },
    { id: 'scenarios', label: '3. Scenarios' },
    { id: 'preview', label: '4. Blueprint' },
    { id: 'sandbox', label: '5. Testing' },
  ];

  return (
    <div className="flex flex-col gap-6 py-4">
      {steps.map((step, idx) => {
        const isActive = current === step.id;
        return (
          <div key={step.id} className="relative flex flex-col items-center">
            <button
              onClick={() => onClick(step.id)}
              className={`z-10 w-10 h-10 rounded-full border-2 flex items-center justify-center transition-all duration-300 sketch-border ${
                isActive 
                  ? 'bg-orange-500 border-orange-400 text-zinc-950 scale-110 shadow-[0_0_15px_#f97316]' 
                  : 'bg-zinc-900 border-zinc-700 text-zinc-500 hover:border-zinc-500'
              }`}
            >
              <span className="font-bold text-xs">{idx + 1}</span>
            </button>
            <span className={`mt-1 handwritten text-[9px] whitespace-nowrap ${isActive ? 'text-orange-500' : 'text-zinc-600'}`}>
              {step.label}
            </span>
            {idx < steps.length - 1 && (
               <div className="h-6 w-0.5 bg-zinc-800 my-1"></div>
            )}
          </div>
        );
      })}
    </div>
  );
};

const BlueprintPart: React.FC<{ template: string; vars: DomainVariables }> = ({ template, vars }) => {
  const renderTextWithHighlights = () => {
    let raw = template;
    return raw.split('\n').map((line, i) => (
      <div key={i} className="mb-1">
        {line.split(/(\*\*.*?\*\*)/).map((part, j) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <span key={j} className="text-zinc-100 font-bold">{part}</span>;
          }
          return <span key={j}>{part}</span>;
        })}
      </div>
    ));
  };

  return <div className="text-zinc-500 leading-relaxed text-xs">{renderTextWithHighlights()}</div>;
};

// --- Main App ---

export default function App() {
  const [vars, setVars] = useState<DomainVariables>(INITIAL_VARIABLES);
  const [activeStep, setActiveStep] = useState<StepId>('identity');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isChatting]);

  const updateVar = useCallback((name: keyof DomainVariables, val: string) => {
    setVars(prev => ({ ...prev, [name]: val }));
  }, []);

  const handleBrainstorm = async (topic: string) => {
    const suggested = await brainstormVariables(topic);
    setVars(prev => ({ ...prev, ...suggested }));
  };

  const finalPrompt = useMemo(() => PROMPT_TEMPLATE(vars), [vars]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isChatting) return;
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');
    setIsChatting(true);

    try {
      const response = await chatWithExpert(finalPrompt, newMessages);
      setMessages([...newMessages, { role: 'model', text: response || 'No response.' }]);
    } catch (e) {
      setMessages([...newMessages, { role: 'model', text: 'Error: Connection lost in the chalk dust.' }]);
    } finally {
      setIsChatting(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(finalPrompt);
    alert('Blueprint copied to clipboard!');
  };

  return (
    <div className="h-screen flex flex-col blueprint-bg selection:bg-orange-500/30 overflow-hidden">
