export default function App() {
  const [vars, setVars] = useState<DomainVariables>(INITIAL_VARIABLES);
  const [activeStep, setActiveStep] = useState<StepId>('identity');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const [brainstormInput, setBrainstormInput] = useState('');
  const [isBrainstorming, setIsBrainstorming] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<{ name: string, data: string, mimeType: string } | null>(null);

  const chatScrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [messages, isChatting]);

  const updateVar = useCallback((name: keyof DomainVariables, val: string) => {
    setVars(prev => ({ ...prev, [name]: val }));
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setUploadedFile({
          name: file.name,
          data: base64String,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleBrainstorm = async () => {
    if (!brainstormInput.trim() && !uploadedFile) return;
    setIsBrainstorming(true);
    const suggested = await brainstormVariables(brainstormInput, uploadedFile || undefined);
    setVars(prev => ({ ...prev, ...suggested }));
    setIsBrainstorming(false);
  };

  const finalPrompt = useMemo(() => PROMPT_TEMPLATE(vars), [vars]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isChatting) return;
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');
    setIsChatting(true);

    try {
      const response = await chatWithExpert(finalPrompt, newMessages);
      setMessages([...newMessages, { role: 'model', text: response || 'No response.' }]);
    } catch (e) {
      setMessages([...newMessages, { role: 'model', text: 'ERROR: CONNECTION_TIMEOUT. RESTARTING_CHAMBER.' }]);
    } finally {
      setIsChatting(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(finalPrompt);
    alert('BLUEPRINT_COPIED');
  };

  return (
    <div className="h-screen flex overflow-hidden">

      {/* Column 1: Navigator */}
      <Navigator current={activeStep} onClick={setActiveStep} />

      {/* Column 2: Form Canvas */}
      <main className="flex-1 flex flex-col bg-black/10 overflow-hidden">
        <header className="p-6 border-b border-white/5 flex justify-between items-center bg-zinc-950/40 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 border-2 border-orange-500 rounded-sm flex items-center justify-center rotate-3">
              <span className="text-orange-500 font-black text-2xl handwritten">M</span>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tighter text-zinc-100">
                MODE<span className="text-orange-500 handwritten ml-1">SHIFT</span>
              </h1>
              <div className="mono text-[8px] text-zinc-500 uppercase tracking-widest flex gap-2">
                <span>Core_Arch_v2.5</span>
                <span className="text-orange-500/50">●</span>
                <span>Active_Session</span>
              </div>
            </div>
          </div>
          <button onClick={copyToClipboard} className="text-[10px] mono border border-orange-500/30 text-orange-500 px-4 py-2 hover:bg-orange-500/10 transition-all uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(249,115,22,0.1)] active:shadow-none translate-y-[-2px] active:translate-y-[0px]">
            Export_Blueprint
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-8 custom-scroll">
          <div className="max-w-xl mx-auto space-y-6">

            {activeStep === 'identity' && (
              <div className="animate-in fade-in duration-500">
                <SketchedCard title="Module: Lightning_Brainstorm">
                  <div className="space-y-4">
                    <div className="flex gap-2">
                      <input 
                        type="text" 
                        placeholder="Input Domain/Role..." 
                        className="flex-1 bg-zinc-900/50 border border-zinc-800 p-2.5 text-xs text-zinc-300 outline-none focus:border-orange-500 transition-all"
                        value={brainstormInput}
                        onChange={(e) => setBrainstormInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleBrainstorm()}
                      />
                      <button 
                        onClick={handleBrainstorm}
                        disabled={isBrainstorming}
                        className="bg-orange-600 text-black px-4 py-1 text-xs font-bold uppercase transition-all hover:bg-orange-500 disabled:opacity-50"
                      >
                        {isBrainstorming ? '...' : 'Sketch'}
                      </button>
                    </div>

                    <div className="flex items-center gap-3">
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        className="hidden" 
                        accept=".pdf,.doc,.docx,.txt"
                      />
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="text-[10px] mono text-zinc-500 border border-zinc-800 px-3 py-1.5 hover:text-zinc-300 hover:border-zinc-700 flex items-center gap-2 uppercase tracking-widest"
                      >
                        <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.414a4 4 0 00-5.656-5.656l-6.415 6.415a6 6 0 108.486 8.486L20.5 13" />
                        </svg>
                        {uploadedFile ? uploadedFile.name : 'Upload Document'}
                      </button>
                      {uploadedFile && (
                        <button 
                          onClick={() => setUploadedFile(null)}
                          className="text-[8px] text-red-500/50 hover:text-red-500 uppercase mono"
                        >
                          [CLEAR]
                        </button>
                      )}
                    </div>
                  </div>
                </SketchedCard>

                <SketchedCard title="Module: Core_Identity">
                  <SketchedInput label="Role Title" value={vars.roleTitle} onChange={(v) => updateVar('roleTitle', v)} placeholder="e.g. Lead Systems Engineer" />
                  <SketchedInput label="Domain Area" value={vars.domainArea} onChange={(v) => updateVar('domainArea', v)} placeholder="e.g. Distributed Infrastructure" />
                  <SketchedInput label="Primary Responsibilities" type="textarea" value={vars.primaryResponsibilities} onChange={(v) => updateVar('primaryResponsibilities', v)} />
                  <div className="grid grid-cols-2 gap-4">
                    <SketchedInput label="Key Systems" value={vars.keySystems} onChange={(v) => updateVar('keySystems', v)} />
                    <SketchedInput label="Task Types" value={vars.commonTaskTypes} onChange={(v) => updateVar('commonTaskTypes', v)} />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'context' && (
              <div className="animate-in fade-in duration-500">
                <SketchedCard title="Module: Communication_Layers">
                  <SketchedInput label="Formal Contexts" value={vars.formalContexts} onChange={(v) => updateVar('formalContexts', v)} />
                  <SketchedInput label="Technical Contexts" value={vars.technicalContexts} onChange={(v) => updateVar('technicalContexts', v)} />
                  <SketchedInput label="Formality Exceptions" value={vars.formalityExceptions} onChange={(v) => updateVar('formalityExceptions', v)} />
                  <div className="grid grid-cols-2 gap-4 border-t border-white/5 pt-4 mt-2">
                    <SketchedInput label="Level" value={vars.expertiseLevel} onChange={(v) => updateVar('expertiseLevel', v)} />
                    <SketchedInput label="Characteristic" value={vars.experienceCharacteristic} onChange={(v) => updateVar('experienceCharacteristic', v)} />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'scenarios' && (
              <div className="animate-in fade-in duration-500 space-y-6">
                <SketchedCard title="Module: Stance_Logic">
                  <div className="space-y-6">
                    <div>
                      <h4 className="handwritten text-orange-500 text-xs mb-2">/URGENT_STATE</h4>
                      <SketchedInput label="Scenario" value={vars.highUrgencyScenario} onChange={(v) => updateVar('highUrgencyScenario', v)} />
                      <SketchedInput label="Style" type="textarea" value={vars.crisisResponseStyle} onChange={(v) => updateVar('crisisResponseStyle', v)} />
                    </div>
                    <div className="border-t border-white/5 pt-4">
                      <h4 className="handwritten text-orange-500 text-xs mb-2">/LEARNING_STATE</h4>
                      <SketchedInput label="Scenario" value={vars.learningScenario} onChange={(v) => updateVar('learningScenario', v)} />
                      <SketchedInput label="Style" type="textarea" value={vars.mentoringStyle} onChange={(v) => updateVar('mentoringStyle', v)} />
                    </div>
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'preview' && (
              <div className="animate-in fade-in duration-500 h-full flex flex-col">
                <SketchedCard title="Module: Source_Code" className="flex-1 flex flex-col">
                  <div className="flex-1 overflow-y-auto mono text-[10px] text-zinc-400 p-4 bg-black/40 border border-white/5 whitespace-pre-wrap leading-relaxed custom-scroll">
                    {finalPrompt}
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'sandbox' && (
              <div className="animate-in fade-in duration-500 h-full flex flex-col">
                <SketchedCard title="Module: Test_Chamber" className="flex-1 flex flex-col min-h-[500px] overflow-hidden">
                  <div ref={chatScrollRef} className="flex-1 overflow-y-auto space-y-4 mb-4 pr-2 custom-scroll scroll-smooth">
                    {messages.length === 0 && (
                      <div className="h-full flex flex-col items-center justify-center opacity-20 italic space-y-2">
                        <div className="w-12 h-12 border border-dashed border-zinc-500 rounded-full animate-spin-slow"></div>
                        <p className="text-[10px] mono">NO_SIGNAL_DETECTED. INITIATE_CONTACT.</p>
                      </div>
                    )}
                    {messages.map((m, i) => (
                      <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`p-3 max-w-[85%] border transition-all ${
                          m.role === 'user' 
                            ? 'bg-orange-600/5 text-orange-500 border-orange-500/40' 
                            : 'bg-zinc-900/80 text-zinc-300 border-zinc-700'
                        } sketch-border`}>
                          <p className="text-xs leading-relaxed">{m.text}</p>
                        </div>
                      </div>
                    ))}
                    {isChatting && (
                      <div className="flex justify-start">
                        <div className="bg-zinc-900 border-zinc-800 p-2 text-zinc-500 italic text-[9px] mono animate-pulse">
                          STREAMING_CORE_DATA...
                        </div>
                      </div>
                    )}
                  </div>
                  <div className="flex gap-2 pt-4 border-t border-white/5">
                    <input 
                      type="text" 
                      value={userInput}
                      onChange={e => setUserInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                      placeholder="Input Vector..."
                      className="flex-1 bg-zinc-950/80 border border-zinc-800 p-2.5 text-xs text-zinc-200 sketch-border outline-none focus:border-orange-500"
                    />
                    <button 
                      onClick={handleSendMessage} 
                      disabled={isChatting || !userInput.trim()}
                      className="w-10 h-10 bg-orange-600 text-black flex items-center justify-center transition-all hover:bg-orange-500 disabled:opacity-20 shadow-[0_0_10px_rgba(249,115,22,0.2)]"
                    >
                      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                      </svg>
                    </button>
                  </div>
                </SketchedCard>
              </div>
            )}

          </div>
        </div>
      </main>

      {/* Column 3: Blueprint Preview */}
      <aside className="hidden lg:flex w-[350px] xl:w-[420px] border-l border-white/5 flex-col bg-zinc-950 p-6 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-4">
          <div className="text-[7px] text-zinc-800 font-bold uppercase rotate-90 origin-bottom-right tracking-widest opacity-40">System_Blueprint_Engine_v4</div>
        </div>

        <div className="mb-8 flex-shrink-0">
          <h4 className="text-[10px] mono font-bold text-zinc-600 uppercase tracking-widest mb-4 flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-orange-500 animate-pulse"></span>
            LIVE_VARIABLE_INJECTION
          </h4>
          <div className="space-y-4">
            <div className="p-3 bg-black/40 border border-zinc-800 rounded-sm relative">
              <span className="absolute -top-1.5 left-2 bg-zinc-950 px-1 text-[7px] text-zinc-500 mono">@PROMPT_ROLE</span>
              <HighlightLabel text={vars.roleTitle} />
            </div>
            <div className="p-3 bg-black/40 border border-zinc-800 rounded-sm relative">
              <span className="absolute -top-1.5 left-2 bg-zinc-950 px-1 text-[7px] text-zinc-500 mono">@PROMPT_DOMAIN</span>
              <HighlightLabel text={vars.domainArea} />
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col overflow-hidden">
          <h4 className="text-[10px] mono font-bold text-zinc-600 uppercase tracking-widest mb-4 flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-zinc-700"></span>
            BLUEPRINT_SOURCE
          </h4>
          <div className="flex-1 bg-zinc-900/30 border border-zinc-800/60 p-5 rounded-xl relative overflow-hidden flex flex-col">
            <div className="flex-1 overflow-y-auto custom-scroll mono text-[9px] leading-relaxed text-zinc-500 pr-1">
              {finalPrompt.split('\n').map((line, i) => (
                <div key={i} className="mb-1">
                  {line.includes(vars.roleTitle) && vars.roleTitle ? (
                    line.split(vars.roleTitle).map((seg, j, arr) => (
                      <React.Fragment key={j}>
                        {seg}
                        {j < arr.length - 1 && <HighlightLabel text={vars.roleTitle} />}
                      </React.Fragment>
                    ))
                  ) : line.includes(vars.domainArea) && vars.domainArea ? (
                    line.split(vars.domainArea).map((seg, j, arr) => (
                      <React.Fragment key={j}>
                        {seg}
                        {j < arr.length - 1 && <HighlightLabel text={vars.domainArea} />}
                      </React.Fragment>
                    ))
                  ) : (
                    line
                  )}
                </div>
              ))}
            </div>

            {/* Visual Trace SVG */}
            <svg className="absolute inset-0 pointer-events-none opacity-5">
              <path d="M 0 100 Q 150 120 300 110" stroke="#f97316" strokeWidth="1" fill="none" className="animate-flow" />
              <path d="M 0 350 Q 150 330 300 340" stroke="#f97316" strokeWidth="1" fill="none" className="animate-flow" />
            </svg>
          </div>
        </div>
      </aside>

      {/* Sketchy Global Footer */}
      <footer className="fixed bottom-0 left-0 right-0 px-6 py-2 border-t border-white/5 bg-zinc-950/80 backdrop-blur-sm flex justify-between items-center z-50">
        <div className="handwritten text-[10px] text-zinc-600 tracking-wider">MODESHIFT_ALPHA // BUILD_2025 // NO_REPRODUCTION</div>
        <div className="flex gap-8 mono text-[9px] text-zinc-800 uppercase">
          <span className={vars.roleTitle ? 'text-orange-500/60' : ''}>VAR_ROLE: {vars.roleTitle ? 'OK' : 'NULL'}</span>
          <span className={vars.domainArea ? 'text-orange-500/60' : ''}>VAR_DOMAIN: {vars.domainArea ? 'OK' : 'NULL'}</span>
        </div>
        <div className="mono text-[9px] text-zinc-600 animate-pulse uppercase tracking-widest">Efficiency_Protocol_Active</div>
      </footer>
    </div>
  );
}

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { DomainVariables, StepId, ChatMessage } from './types';
import { INITIAL_VARIABLES, PROMPT_TEMPLATE } from './constants';
import { brainstormVariables, chatWithExpert } from './services/geminiService';

// --- Atomic Components ---

const HighlightLabel: React.FC<{ text: string }> = ({ text }) => (
  <span className="handwritten text-orange-500 bg-orange-500/5 px-1 py-0.5 rounded-sm border-b border-orange-500/30 whitespace-nowrap inline-block">
    {text || '[UNDEFINED]'}
  </span>
);

const SketchedCard: React.FC<{ children: React.ReactNode; className?: string; title?: string }> = ({ children, className = '', title }) => (
  <div className={`sketch-border bg-zinc-900/40 p-4 sm:p-6 mb-6 relative group transition-all duration-300 hover:bg-zinc-900/60 ${className}`}>
    {title && (
      <div className="absolute -top-3 left-4 bg-zinc-950 px-2 handwritten text-[10px] text-orange-500 uppercase tracking-widest border border-white/5">
        {title}
      </div>
    )}
    {children}
  </div>
);

const SketchedInput: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  type?: 'text' | 'textarea';
}> = ({ label, value, onChange, placeholder, type = 'text' }) => {
  const [isFocused, setIsFocused] = useState(false);

  return (
    <div className="mb-4">
      <label className="block mono text-[9px] uppercase font-bold text-zinc-600 mb-1 tracking-tighter">
        {label}
      </label>
      {type === 'textarea' ? (
        <textarea
          rows={3}
          value={value}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={`w-full bg-black/40 p-3 text-xs text-zinc-300 outline-none transition-all duration-300 ${
            isFocused ? 'sketch-border-active' : 'sketch-border'
          }`}
        />
      ) : (
        <input
          type="text"
          value={value}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={`w-full bg-black/40 p-3 text-xs text-zinc-300 outline-none transition-all duration-300 ${
            isFocused ? 'sketch-border-active' : 'sketch-border'
          }`}
        />
      )}
    </div>
  );
};

// --- Responsive Navigator ---

const Navigator: React.FC<{ current: StepId; onClick: (s: StepId) => void }> = ({ current, onClick }) => {
  const steps: { id: StepId; icon: string; label: string }[] = [
    { id: 'identity', icon: '1', label: 'Identity' },
    { id: 'context', icon: '2', label: 'Context' },
    { id: 'scenarios', icon: '3', label: 'Stance' },
    { id: 'preview', icon: '4', label: 'Source' },
    { id: 'sandbox', icon: '5', label: 'Sandbox' },
  ];

  return (
    <nav className="flex lg:flex-col items-center justify-around lg:justify-start lg:py-8 lg:gap-8 bg-zinc-950 border-t lg:border-t-0 lg:border-r border-white/5 w-full lg:w-20 h-16 lg:h-full z-40 fixed lg:static bottom-0 left-0">
      {steps.map((step) => {
        const isActive = current === step.id;
        return (
          <button
            key={step.id}
            onClick={() => onClick(step.id)}
            className="group relative flex flex-col items-center flex-1 lg:flex-none"
          >
            <div className={`w-9 h-9 sm:w-10 sm:h-10 rounded-full border-2 flex items-center justify-center handwritten text-base transition-all duration-300 ${
              isActive 
                ? 'bg-orange-500 border-orange-400 text-black scale-110' 
                : 'border-zinc-800 text-zinc-600 hover:border-zinc-500'
            }`}>
              {step.icon}
            </div>
            <span className={`text-[8px] mono mt-1 uppercase tracking-tighter lg:hidden ${isActive ? 'text-orange-500' : 'text-zinc-700'}`}>
              {step.label}
            </span>
            <div className={`hidden lg:block absolute top-1/2 left-14 -translate-y-1/2 bg-zinc-900 px-3 py-1 text-[8px] uppercase mono tracking-widest border border-white/10 opacity-0 group-hover:opacity-100 transition-all duration-300 whitespace-nowrap z-50 pointer-events-none`}>
              {step.id}
            </div>
          </button>
        );
      })}
    </nav>
  );
};

// --- Main Application ---

export default function App() {
  const [vars, setVars] = useState<DomainVariables>(INITIAL_VARIABLES);
  const [activeStep, setActiveStep] = useState<StepId>('identity');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const [brainstormInput, setBrainstormInput] = useState('');
  const [isBrainstorming, setIsBrainstorming] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<{ name: string, data: string, mimeType: string } | null>(null);

  const chatScrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [messages, isChatting]);

  const updateVar = useCallback((name: keyof DomainVariables, val: string) => {
    setVars(prev => ({ ...prev, [name]: val }));
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setUploadedFile({
          name: file.name,
          data: base64String,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleBrainstorm = async () => {
    if (!brainstormInput.trim() && !uploadedFile) return;
    setIsBrainstorming(true);
    try {
      const suggested = await brainstormVariables(brainstormInput, uploadedFile || undefined);
      setVars(prev => ({ ...prev, ...suggested }));
    } catch (e) {
      console.error("Brainstorm failed", e);
    } finally {
      setIsBrainstorming(false);
    }
  };

  const finalPrompt = useMemo(() => PROMPT_TEMPLATE(vars), [vars]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isChatting) return;
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');
    setIsChatting(true);

    try {
      const response = await chatWithExpert(finalPrompt, newMessages);
      setMessages([...newMessages, { role: 'model', text: response || 'No response.' }]);
    } catch (e) {
      setMessages([...newMessages, { role: 'model', text: 'ERROR: SIGNAL_LOST. CHAMBER_ISOLATED.' }]);
    } finally {
      setIsChatting(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(finalPrompt);
    alert('BLUEPRINT_SYNCED');
  };

  return (
    <div className="h-screen flex flex-col lg:flex-row bg-zinc-950 text-zinc-200 overflow-hidden">

      {/* Column 1: Navigator */}
      <Navigator current={activeStep} onClick={setActiveStep} />

      {/* Column 2: Content Canvas */}
      <main className="flex-1 flex flex-col min-w-0 bg-black/20 pb-16 lg:pb-0 overflow-hidden">
        <header className="p-4 sm:p-6 border-b border-white/5 flex justify-between items-center bg-zinc-950/80 backdrop-blur-md z-30">
          <div className="flex items-center gap-3 sm:gap-4">
            <div className="w-8 h-8 sm:w-10 sm:h-10 border-2 border-orange-500 rounded-sm flex items-center justify-center rotate-3 flex-shrink-0">
              <span className="text-orange-500 font-black text-xl sm:text-2xl handwritten">M</span>
            </div>
            <div className="min-w-0">
              <h1 className="text-lg sm:text-xl font-bold tracking-tighter truncate">
                MODE<span className="text-orange-500 handwritten ml-1">SHIFT</span>
              </h1>
              <div className="mono text-[7px] sm:text-[8px] text-zinc-600 uppercase tracking-widest flex items-center gap-2">
                <span className="hidden sm:inline">Build_v3.0.0</span>
                <span className="text-orange-500/30">●</span>
                <span className="truncate">Expert_Architect</span>
              </div>
            </div>
          </div>
          <button 
            onClick={copyToClipboard} 
            className="text-[9px] sm:text-[10px] mono border border-orange-500/30 text-orange-500 px-3 sm:px-4 py-1.5 sm:py-2 hover:bg-orange-500/10 transition-all uppercase tracking-widest active:scale-95 flex-shrink-0"
          >
            Export_Raw
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 sm:p-8 custom-scroll">
          <div className="max-w-2xl mx-auto">

            {activeStep === 'identity' && (
              <div className="animate-in fade-in duration-700 slide-in-from-bottom-2">
                <SketchedCard title="Module: Context_Injection">
                  <div className="space-y-4">
                    <div className="flex gap-2">
                      <input 
                        type="text" 
                        placeholder="Define Role or Topic..." 
                        className="flex-1 bg-black/40 border border-zinc-800 p-3 text-xs text-zinc-300 outline-none focus:border-orange-500 transition-all"
                        value={brainstormInput}
                        onChange={(e) => setBrainstormInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleBrainstorm()}
                      />
                      <button 
                        onClick={handleBrainstorm}
                        disabled={isBrainstorming}
                        className="bg-orange-600 text-black px-4 py-2 text-[10px] font-bold uppercase transition-all hover:bg-orange-500 disabled:opacity-50 flex-shrink-0"
                      >
                        {isBrainstorming ? '...' : 'Sketch'}
                      </button>
                    </div>

                    <div className="flex flex-wrap items-center gap-3">
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        className="hidden" 
                        accept=".pdf,.doc,.docx,.txt"
                      />
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="text-[9px] mono text-zinc-500 border border-zinc-800 px-3 py-2 hover:text-zinc-300 hover:border-zinc-700 flex items-center gap-2 uppercase tracking-widest transition-colors"
                      >
                        <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        {uploadedFile ? uploadedFile.name : 'Ingest_Document'}
                      </button>
                      {uploadedFile && (
                        <button 
                          onClick={() => setUploadedFile(null)}
                          className="text-[8px] text-red-500/50 hover:text-red-500 uppercase mono underline"
                        >
                          [PURGE]
                        </button>
                      )}
                    </div>
                  </div>
                </SketchedCard>

                <SketchedCard title="Module: Core_Blueprint_V1">
                  <SketchedInput label="Role Title" value={vars.roleTitle} onChange={(v) => updateVar('roleTitle', v)} placeholder="e.g. Senior Kernel Engineer" />
                  <SketchedInput label="Domain Area" value={vars.domainArea} onChange={(v) => updateVar('domainArea', v)} placeholder="e.g. Low-level Systems & Resource Management" />
                  <SketchedInput label="Key Responsibilities" type="textarea" value={vars.primaryResponsibilities} onChange={(v) => updateVar('primaryResponsibilities', v)} />
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <SketchedInput label="Primary Systems" value={vars.keySystems} onChange={(v) => updateVar('keySystems', v)} />
                    <SketchedInput label="Workstream Types" value={vars.commonTaskTypes} onChange={(v) => updateVar('commonTaskTypes', v)} />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'context' && (
              <div className="animate-in fade-in duration-700 slide-in-from-bottom-2">
                <SketchedCard title="Module: Communication_Protocols">
                  <SketchedInput label="Formal Delivery Contexts" value={vars.formalContexts} onChange={(v) => updateVar('formalContexts', v)} />
                  <SketchedInput label="Deep Technical Contexts" value={vars.technicalContexts} onChange={(v) => updateVar('technicalContexts', v)} />
                  <SketchedInput label="Syntactic Constraints" value={vars.formalityExceptions} onChange={(v) => updateVar('formalityExceptions', v)} />
                  <div className="grid grid-cols-2 gap-4 border-t border-white/5 pt-4 mt-2">
                    <SketchedInput label="Mastery_Level" value={vars.expertiseLevel} onChange={(v) => updateVar('expertiseLevel', v)} />
                    <SketchedInput label="Trait_Signature" value={vars.experienceCharacteristic} onChange={(v) => updateVar('experienceCharacteristic', v)} />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'scenarios' && (
              <div className="animate-in fade-in duration-700 slide-in-from-bottom-2 space-y-6">
                <SketchedCard title="Module: Behavioral_Matrix">
                  <div className="space-y-6">
                    <div>
                      <h4 className="handwritten text-orange-500 text-xs mb-3">STATE_01: HIGH_URGENCY</h4>
                      <SketchedInput label="Scenario Vector" value={vars.highUrgencyScenario} onChange={(v) => updateVar('highUrgencyScenario', v)} />
                      <SketchedInput label="Response Signature" type="textarea" value={vars.crisisResponseStyle} onChange={(v) => updateVar('crisisResponseStyle', v)} />
                    </div>
                    <div className="border-t border-white/5 pt-6">
                      <h4 className="handwritten text-orange-500 text-xs mb-3">STATE_02: PEDAGOGICAL_TRANSFER</h4>
                      <SketchedInput label="Scenario Vector" value={vars.learningScenario} onChange={(v) => updateVar('learningScenario', v)} />
                      <SketchedInput label="Pedagogy Signature" type="textarea" value={vars.mentoringStyle} onChange={(v) => updateVar('mentoringStyle', v)} />
                    </div>
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'preview' && (
              <div className="animate-in fade-in duration-700 h-full flex flex-col">
                <SketchedCard title="Module: Raw_Output_Buffer" className="flex-1 flex flex-col">
                  <div className="flex-1 overflow-y-auto mono text-[9px] sm:text-[10px] text-zinc-500 p-4 bg-black/50 sketch-border border-white/5 whitespace-pre-wrap leading-relaxed custom-scroll">
                    {finalPrompt}
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'sandbox' && (
              <div className="animate-in fade-in duration-700 h-full flex flex-col overflow-hidden min-h-[500px]">
                <SketchedCard title="Module: Live_Emulation_Chamber" className="flex-1 flex flex-col overflow-hidden">
                  <div ref={chatScrollRef} className="flex-1 overflow-y-auto space-y-4 mb-4 pr-2 custom-scroll scroll-smooth">
                    {messages.length === 0 && (
                      <div className="h-full flex flex-col items-center justify-center opacity-20 italic space-y-3">
                        <div className="w-12 h-12 border border-dashed border-orange-500/50 rounded-full animate-[spin_8s_linear_infinite]"></div>
                        <p className="text-[10px] mono tracking-widest uppercase">Awaiting_Neural_Input</p>
                      </div>
                    )}
                    {messages.map((m, i) => (
                      <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`p-3 max-w-[90%] sm:max-w-[85%] border transition-all duration-300 ${
                          m.role === 'user' 
                            ? 'bg-orange-500/5 text-orange-400 border-orange-500/30' 
                            : 'bg-zinc-800/40 text-zinc-300 border-zinc-700/50'
                        } sketch-border`}>
                          <p className="text-xs leading-relaxed">{m.text}</p>
                        </div>
                      </div>
                    ))}
                    {isChatting && (
                      <div className="flex justify-start">
                        <div className="bg-zinc-900 border border-zinc-800 p-2 text-zinc-600 italic text-[9px] mono animate-pulse">
                          PROCESSING_VECTOR_MATRIX...
                        </div>
                      </div>
                    )}
                  </div>
                  <div className="flex gap-2 pt-4 border-t border-white/5 flex-shrink-0">
                    <input 
                      type="text" 
                      value={userInput}
                      onChange={e => setUserInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                      placeholder="Input_Test_Case..."
                      className="flex-1 bg-black/40 border border-zinc-800 p-3 text-xs text-zinc-200 sketch-border outline-none focus:border-orange-500 transition-colors"
                    />
                    <button 
                      onClick={handleSendMessage} 
                      disabled={isChatting || !userInput.trim()}
                      className="w-11 h-11 bg-orange-600 text-black flex items-center justify-center transition-all hover:bg-orange-500 disabled:opacity-20 flex-shrink-0"
                    >
                      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                      </svg>
                    </button>
                  </div>
                </SketchedCard>
              </div>
            )}

          </div>
        </div>
      </main>

      {/* Column 3: Blueprint Preview - Only Desktop */}
      <aside className="hidden lg:flex w-[350px] xl:w-[450px] border-l border-white/5 flex-col bg-zinc-950 p-6 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-4">
          <div className="text-[7px] text-zinc-800 font-bold uppercase rotate-90 origin-bottom-right tracking-[0.3em] opacity-40">SYSTEM_ARCH_CORE_04</div>
        </div>

        <div className="mb-8 flex-shrink-0">
          <h4 className="text-[10px] mono font-bold text-zinc-700 uppercase tracking-widest mb-5 flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-orange-500 animate-pulse"></span>
            ACTIVE_VARIABLE_STREAM
          </h4>
          <div className="space-y-4">
            <div className="p-3 bg-zinc-900/30 border border-white/5 sketch-border relative">
              <span className="absolute -top-1.5 left-2 bg-zinc-950 px-1 text-[7px] text-zinc-700 mono">PROMPT_ROLE</span>
              <HighlightLabel text={vars.roleTitle} />
            </div>
            <div className="p-3 bg-zinc-900/30 border border-white/5 sketch-border relative">
              <span className="absolute -top-1.5 left-2 bg-zinc-950 px-1 text-[7px] text-zinc-700 mono">PROMPT_DOMAIN</span>
              <HighlightLabel text={vars.domainArea} />
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <h4 className="text-[10px] mono font-bold text-zinc-700 uppercase tracking-widest mb-4 flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-zinc-800"></span>
            BLUEPRINT_PREVIEW
          </h4>
          <div className="flex-1 bg-zinc-900/10 border border-white/5 p-5 rounded-2xl relative overflow-hidden flex flex-col">
            <div className="flex-1 overflow-y-auto custom-scroll mono text-[9px] leading-relaxed text-zinc-600 pr-2">
              {finalPrompt.split('\n').map((line, i) => (
                <div key={i} className="mb-1">
                  {line.includes(vars.roleTitle) && vars.roleTitle ? (
                    line.split(vars.roleTitle).map((seg, j, arr) => (
                      <React.Fragment key={j}>
                        {seg}
                        {j < arr.length - 1 && <HighlightLabel text={vars.roleTitle} />}
                      </React.Fragment>
                    ))
                  ) : line.includes(vars.domainArea) && vars.domainArea ? (
                    line.split(vars.domainArea).map((seg, j, arr) => (
                      <React.Fragment key={j}>
                        {seg}
                        {j < arr.length - 1 && <HighlightLabel text={vars.domainArea} />}
                      </React.Fragment>
                    ))
                  ) : (
                    line
                  )}
                </div>
              ))}
            </div>

            {/* Visual Trace Decorations */}
            <svg className="absolute inset-0 pointer-events-none opacity-[0.03]">
              <path d="M 0 50 Q 150 70 300 60" stroke="#f97316" strokeWidth="1" fill="none" className="animate-flow" />
              <path d="M 0 250 Q 150 230 300 240" stroke="#f97316" strokeWidth="1" fill="none" className="animate-flow" />
              <path d="M 100 0 Q 120 150 110 300" stroke="#f97316" strokeWidth="0.5" fill="none" />
            </svg>
          </div>
        </div>
      </aside>

      {/* Global Footer Status Bar */}
      <footer className="fixed bottom-0 left-0 right-0 h-8 sm:h-10 px-4 sm:px-6 border-t border-white/5 bg-zinc-950/90 backdrop-blur-md flex justify-between items-center z-50 text-[7px] sm:text-[9px] mono text-zinc-700">
        <div className="handwritten tracking-widest opacity-60">MODESHIFT_ALPHA // BUILD_2025 // SECURE_ARCH</div>
        <div className="hidden sm:flex gap-8 uppercase">
          <span className={vars.roleTitle ? 'text-orange-500/40' : ''}>VAR_ROLE: {vars.roleTitle ? 'LOCKED' : 'NULL'}</span>
          <span className={vars.domainArea ? 'text-orange-500/40' : ''}>VAR_DOMAIN: {vars.domainArea ? 'LOCKED' : 'NULL'}</span>
        </div>
        <div className="animate-pulse uppercase tracking-widest text-orange-500/40 font-bold">Protocol_Active</div>
      </footer>
    </div>
  );
}

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { DomainVariables, StepId, ChatMessage } from './types';
import { INITIAL_VARIABLES, PROMPT_TEMPLATE } from './constants';
import { brainstormVariables, chatWithExpert } from './services/geminiService';

// --- Atomic Components ---

const HighlightLabel: React.FC<{ text: string }> = ({ text }) => (
  <span className="handwritten text-orange-500 bg-orange-500/5 px-1 py-0.5 rounded-sm border-b border-orange-500/30 whitespace-nowrap inline-block">
    {text || '[UNDEFINED]'}
  </span>
);

const SketchedCard: React.FC<{ children: React.ReactNode; className?: string; title?: string }> = ({ children, className = '', title }) => (
  <div className={`sketch-border bg-zinc-900/40 p-4 md:p-6 mb-6 relative group transition-all duration-500 hover:bg-zinc-900/60 ${className}`}>
    {title && (
      <div className="absolute -top-3 left-4 bg-zinc-950 px-2 handwritten text-[10px] text-orange-500 uppercase tracking-widest border border-white/5 z-10">
        {title}
      </div>
    )}
    {children}
  </div>
);

const SketchedInput: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  type?: 'text' | 'textarea';
}> = ({ label, value, onChange, placeholder, type = 'text' }) => {
  const [isFocused, setIsFocused] = useState(false);

  return (
    <div className="mb-4">
      <label className="block mono text-[9px] uppercase font-bold text-zinc-600 mb-1 tracking-tighter">
        {label}
      </label>
      {type === 'textarea' ? (
        <textarea
          rows={3}
          value={value}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={`w-full bg-black/40 p-3 text-xs text-zinc-300 outline-none transition-all duration-300 custom-scroll ${
            isFocused ? 'sketch-border-active border-orange-500/50' : 'sketch-border'
          }`}
        />
      ) : (
        <input
          type="text"
          value={value}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={`w-full bg-black/40 p-3 text-xs text-zinc-300 outline-none transition-all duration-300 ${
            isFocused ? 'sketch-border-active border-orange-500/50' : 'sketch-border'
          }`}
        />
      )}
    </div>
  );
};

// --- Responsive Navigator ---

const Navigator: React.FC<{ current: StepId; onClick: (s: StepId) => void }> = ({ current, onClick }) => {
  const steps: { id: StepId; icon: string; label: string }[] = [
    { id: 'identity', icon: '01', label: 'Identity' },
    { id: 'context', icon: '02', label: 'Context' },
    { id: 'scenarios', icon: '03', label: 'Behavior' },
    { id: 'preview', icon: '04', label: 'Source' },
    { id: 'sandbox', icon: '05', label: 'Sandbox' },
  ];

  return (
    <nav className="flex lg:flex-col items-center justify-around lg:justify-start lg:py-10 lg:gap-10 bg-zinc-950 border-t lg:border-t-0 lg:border-r border-white/5 w-full lg:w-24 h-20 lg:h-full z-40 fixed lg:static bottom-0 left-0 shadow-2xl lg:shadow-none">
      {steps.map((step) => {
        const isActive = current === step.id;
        return (
          <button
            key={step.id}
            onClick={() => onClick(step.id)}
            className="group relative flex flex-col items-center flex-1 lg:flex-none"
          >
            <div className={`w-10 h-10 rounded-full border-2 flex items-center justify-center handwritten text-sm transition-all duration-500 ${
              isActive 
                ? 'bg-orange-600 border-orange-400 text-black scale-110 shadow-[0_0_25px_#f9731633]' 
                : 'border-zinc-800 text-zinc-600 hover:border-zinc-600'
            }`}>
              {step.icon}
            </div>
            <span className={`text-[8px] mono mt-1.5 uppercase tracking-tighter lg:hidden font-bold ${isActive ? 'text-orange-500' : 'text-zinc-700'}`}>
              {step.label}
            </span>
            <div className={`hidden lg:block absolute top-1/2 left-16 -translate-y-1/2 bg-zinc-900 px-3 py-1 text-[8px] uppercase mono tracking-widest border border-white/10 opacity-0 group-hover:opacity-100 transition-all duration-300 whitespace-nowrap z-50 pointer-events-none translate-x-[-10px] group-hover:translate-x-0`}>
              {step.label}
            </div>
          </button>
        );
      })}
    </nav>
  );
};

// --- Main Application ---

export default function App() {
  const [vars, setVars] = useState<DomainVariables>(INITIAL_VARIABLES);
  const [activeStep, setActiveStep] = useState<StepId>('identity');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const [brainstormInput, setBrainstormInput] = useState('');
  const [isBrainstorming, setIsBrainstorming] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<{ name: string, data: string, mimeType: string } | null>(null);

  const chatScrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [messages, isChatting]);

  const updateVar = useCallback((name: keyof DomainVariables, val: string) => {
    setVars(prev => ({ ...prev, [name]: val }));
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setUploadedFile({
          name: file.name,
          data: base64String,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleBrainstorm = async () => {
    if (!brainstormInput.trim() && !uploadedFile) return;
    setIsBrainstorming(true);
    try {
      const suggested = await brainstormVariables(brainstormInput, uploadedFile || undefined);
      setVars(prev => ({ ...prev, ...suggested }));
    } catch (e) {
      console.error("Brainstorm failed", e);
    } finally {
      setIsBrainstorming(false);
    }
  };

  const finalPrompt = useMemo(() => PROMPT_TEMPLATE(vars), [vars]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isChatting) return;
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');
    setIsChatting(true);

    try {
      const response = await chatWithExpert(finalPrompt, newMessages);
      setMessages([...newMessages, { role: 'model', text: response || 'No response.' }]);
    } catch (e) {
      setMessages([...newMessages, { role: 'model', text: 'ERROR: SIGNAL_TIMEOUT. ATTEMPTING_RECOVERY.' }]);
    } finally {
      setIsChatting(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(finalPrompt);
    // Simple visual feedback instead of alert
    const btn = document.getElementById('copy-btn');
    if (btn) {
      const originalText = btn.innerText;
      btn.innerText = 'SYNCED_OK';
      setTimeout(() => btn.innerText = originalText, 2000);
    }
  };

  const renderPreview = () => {
    return finalPrompt.split('\n').map((line, i) => {
      if (!line.trim()) return <br key={i} />;

      let elements: React.ReactNode[] = [line];

      // Simple variable highlighting in preview
      const checkVars: (keyof DomainVariables)[] = ['roleTitle', 'domainArea', 'expertiseLevel'];
      checkVars.forEach(vKey => {
        const val = vars[vKey];
        if (val && line.includes(val)) {
          const parts = line.split(val);
          const newElements: React.ReactNode[] = [];
          parts.forEach((p, idx) => {
            newElements.push(p);
            if (idx < parts.length - 1) {
              newElements.push(<HighlightLabel key={`${i}-${idx}`} text={val} />);
            }
          });
          elements = newElements;
        }
      });

      return <div key={i} className="mb-1">{elements}</div>;
    });
  };

  return (
    <div className="h-screen flex flex-col lg:flex-row bg-zinc-950 text-zinc-200 overflow-hidden font-sans">

      {/* Column 1: Navigator */}
      <Navigator current={activeStep} onClick={setActiveStep} />

      {/* Column 2: Content Canvas */}
      <main className="flex-1 flex flex-col min-w-0 bg-black/30 pb-20 lg:pb-0 overflow-hidden relative">
        <div className="absolute inset-0 blueprint-dots opacity-20 pointer-events-none"></div>

        <header className="px-6 py-5 border-b border-white/5 flex justify-between items-center bg-zinc-950/90 backdrop-blur-xl z-30">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 border-2 border-orange-500 rounded-sm flex items-center justify-center rotate-6 flex-shrink-0 transition-transform hover:rotate-0 duration-500">
              <span className="text-orange-500 font-black text-2xl handwritten">M</span>
            </div>
            <div className="min-w-0">
              <h1 className="text-xl font-bold tracking-tighter truncate leading-none mb-1">
                MODE<span className="text-orange-500 handwritten ml-1">SHIFT</span>
              </h1>
              <div className="mono text-[8px] text-zinc-600 uppercase tracking-[0.2em] flex items-center gap-2">
                <span className="hidden sm:inline">CORE_SYS_3.1</span>
                <span className="text-orange-500/20">●</span>
                <span className="truncate">DOMAIN_PROTOCOL_ALPHA</span>
              </div>
            </div>
          </div>
          <button 
            id="copy-btn"
            onClick={copyToClipboard} 
            className="text-[10px] mono border border-orange-500/20 text-orange-500 px-4 py-2 hover:bg-orange-500/10 transition-all uppercase tracking-widest active:scale-95 active:bg-orange-500/20 flex-shrink-0"
          >
            Export_Raw
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-10 lg:p-14 custom-scroll relative z-10">
          <div className="max-w-2xl mx-auto">

            {activeStep === 'identity' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                <SketchedCard title="Module: Context_Extraction">
                  <div className="space-y-5">
                    <div className="flex flex-col sm:flex-row gap-3">
                      <input 
                        type="text" 
                        placeholder="Define Role, Domain, or Expert Topic..." 
                        className="flex-1 bg-black/60 border border-zinc-800 p-3.5 text-xs text-zinc-300 outline-none focus:border-orange-500 transition-all placeholder:text-zinc-700"
                        value={brainstormInput}
                        onChange={(e) => setBrainstormInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleBrainstorm()}
                      />
                      <button 
                        onClick={handleBrainstorm}
                        disabled={isBrainstorming}
                        className="bg-orange-600 text-black px-6 py-3 text-[10px] font-bold uppercase transition-all hover:bg-orange-500 disabled:opacity-50 flex-shrink-0 active:scale-95 shadow-lg shadow-orange-950/20"
                      >
                        {isBrainstorming ? '...' : 'Sketch_AI'}
                      </button>
                    </div>

                    <div className="flex flex-wrap items-center gap-4 pt-2">
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        className="hidden" 
                        accept=".pdf,.doc,.docx,.txt"
                      />
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="text-[9px] mono text-zinc-500 border border-dashed border-zinc-800 px-4 py-2.5 hover:text-orange-400 hover:border-orange-900 flex items-center gap-3 uppercase tracking-[0.15em] transition-all bg-black/20"
                      >
                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                        </svg>
                        {uploadedFile ? uploadedFile.name : 'Ingest_Reference_Doc'}
                      </button>
                      {uploadedFile && (
                        <button 
                          onClick={() => setUploadedFile(null)}
                          className="text-[8px] text-zinc-600 hover:text-red-500 uppercase mono underline underline-offset-4 decoration-zinc-800"
                        >
                          [PURGE_FILE]
                        </button>
                      )}
                    </div>
                  </div>
                </SketchedCard>

                <SketchedCard title="Module: Identity_Matrix">
                  <div className="grid grid-cols-1 gap-1">
                    <SketchedInput label="Expert Role Title" value={vars.roleTitle} onChange={(v) => updateVar('roleTitle', v)} placeholder="e.g. Lead Cybersecurity Architect" />
                    <SketchedInput label="Domain Specialization" value={vars.domainArea} onChange={(v) => updateVar('domainArea', v)} placeholder="e.g. Zero-Trust Cloud Infrastructure" />
                    <SketchedInput label="Primary Functions" type="textarea" value={vars.primaryResponsibilities} onChange={(v) => updateVar('primaryResponsibilities', v)} placeholder="Identify key daily objectives..." />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-x-4">
                    <SketchedInput label="Key Ecosystems" value={vars.keySystems} onChange={(v) => updateVar('keySystems', v)} placeholder="AWS, Splunk, SIEM..." />
                    <SketchedInput label="Core Task Types" value={vars.commonTaskTypes} onChange={(v) => updateVar('commonTaskTypes', v)} placeholder="Audit, Response, Design..." />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'context' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                <SketchedCard title="Module: Linguistics_Calibration">
                  <div className="grid grid-cols-1 gap-2">
                    <SketchedInput label="Formal Delivery Contexts" value={vars.formalContexts} onChange={(v) => updateVar('formalContexts', v)} />
                    <SketchedInput label="Technical Deep-Dive Contexts" value={vars.technicalContexts} onChange={(v) => updateVar('technicalContexts', v)} />
                    <SketchedInput label="Zero-Contraction Constraints" value={vars.formalityExceptions} onChange={(v) => updateVar('formalityExceptions', v)} />
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 border-t border-white/5 pt-6 mt-4">
                    <SketchedInput label="Seniority_Tier" value={vars.expertiseLevel} onChange={(v) => updateVar('expertiseLevel', v)} />
                    <SketchedInput label="Tenure_Characteristic" value={vars.experienceCharacteristic} onChange={(v) => updateVar('experienceCharacteristic', v)} />
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'scenarios' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 space-y-8">
                <SketchedCard title="Module: Adaptive_Logic_Flow">
                  <div className="space-y-8">
                    <div>
                      <h4 className="handwritten text-orange-500 text-xs mb-3 tracking-widest opacity-80 uppercase">Trigger: High_Urgency</h4>
                      <SketchedInput label="Vector Scenario" value={vars.highUrgencyScenario} onChange={(v) => updateVar('highUrgencyScenario', v)} />
                      <SketchedInput label="Behavioral Response" type="textarea" value={vars.crisisResponseStyle} onChange={(v) => updateVar('crisisResponseStyle', v)} />
                    </div>
                    <div className="border-t border-white/5 pt-8">
                      <h4 className="handwritten text-orange-500 text-xs mb-3 tracking-widest opacity-80 uppercase">Trigger: Knowledge_Transfer</h4>
                      <SketchedInput label="Vector Scenario" value={vars.learningScenario} onChange={(v) => updateVar('learningScenario', v)} />
                      <SketchedInput label="Mentorship Stance" type="textarea" value={vars.mentoringStyle} onChange={(v) => updateVar('mentoringStyle', v)} />
                    </div>
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'preview' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 h-full flex flex-col">
                <SketchedCard title="Module: Compiled_Blueprint" className="flex-1 flex flex-col min-h-[500px]">
                  <div className="flex-1 overflow-y-auto mono text-[9px] sm:text-[10px] text-zinc-500 p-5 bg-black/60 sketch-border border-white/5 whitespace-pre-wrap leading-loose custom-scroll selection:bg-orange-500/20">
                    {finalPrompt}
                  </div>
                </SketchedCard>
              </div>
            )}

            {activeStep === 'sandbox' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 h-full flex flex-col overflow-hidden min-h-[500px]">
                <SketchedCard title="Module: Live_Emulation_Chamber" className="flex-1 flex flex-col overflow-hidden">
                  <div ref={chatScrollRef} className="flex-1 overflow-y-auto space-y-6 mb-4 pr-3 custom-scroll scroll-smooth">
                    {messages.length === 0 && (
                      <div className="h-full flex flex-col items-center justify-center opacity-30 italic space-y-4">
                        <div className="w-16 h-16 border border-dashed border-orange-500/40 rounded-full glow-pulse"></div>
                        <p className="text-[10px] mono tracking-[0.3em] uppercase text-center">System_Idle<br/>Awaiting_Interaction_Matrix</p>
