                    {messages.map((m, i) => (
                      <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`p-4 max-w-[92%] sm:max-w-[85%] border transition-all duration-500 ${
                          m.role === 'user' 
                            ? 'bg-orange-500/5 text-orange-400 border-orange-500/30' 
                            : 'bg-zinc-800/40 text-zinc-300 border-zinc-700/60'
                        } sketch-border`}>
                          <p className="text-xs leading-relaxed">{m.text}</p>
                        </div>
