                    <div className="border-t-2 border-white/5 pt-12">
                      <h4 className="handwritten text-orange-500 text-sm font-bold mb-5 tracking-[0.2em] uppercase text-shadow-vivid">State: KNOWLEDGE_INHERITANCE</h4>
